def copy_meeting_links(apps, schema_editor):
    Task = apps.get_model("crm", "Task")
    Link = Task.meetings.through
    Link.objects.bulk_create([Link(task_id=pk, meeting_id=mid) for pk, mid in
                              Task.objects.exclude(meeting=None).values_list("pk", "meeting_id")])


def copy_back(apps, schema_editor):
    Task = apps.get_model("crm", "Task")
    for link in Task.meetings.through.objects.order_by("-meeting__start"):
        Task.objects.filter(pk=link.task_id).update(meeting_id=link.meeting_id)


